import React, { useEffect, useState } from 'react';

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // modal
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState({
    id: null,
    nom: '',
    referencia: '',
    descripcio: '',
    quantitat: 0,
  });

  const token = localStorage.getItem('token');

  /* ======================
     FETCH PRODUCTES
  ====================== */
  const fetchProducts = async () => {
    try {
      const res = await fetch('http://localhost/api/productes', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();
      setProducts(data);
    } catch (err) {
      setError('Error al obtenir els productes');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  /* ======================
     ELIMINAR
  ====================== */
  const handleDelete = async (id) => {
    if (!window.confirm('Segur que vols eliminar aquest producte?')) return;

    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();

      if (!data.exit) {
        alert(data.missatge);
        return;
      }

      // eliminar del state
      setProducts(products.filter((p) => p.id !== id));
    } catch (err) {
      alert('Error eliminant el producte');
    }
  };

  /* ======================
     EDITAR (ABRIR MODAL)
  ====================== */
  const handleEdit = (producte) => {
    setForm(producte);
    setShowModal(true);
  };

  /* ======================
     INPUTS MODAL
  ====================== */
  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  /* ======================
     GUARDAR EDIT
  ====================== */
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const res = await fetch(
        `http://localhost/api/productes/${form.id}`,
        {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(form),
        }
      );

      const data = await res.json();

      if (!data.exit) {
        alert(data.missatge || 'Error guardant');
        return;
      }

      setShowModal(false);
      fetchProducts();
    } catch (err) {
      alert('Error guardant el producte');
    }
  };

  if (loading) return <p>Carregant...</p>;
  if (error) return <p className="text-danger">{error}</p>;

  return (
    <div>
      <h2>Productes</h2>

      {products.length === 0 ? (
        <p>No hi ha productes disponibles.</p>
      ) : (
        <table className="table table-striped">
          <thead>
            <tr>
              <th>Nom</th>
              <th>Referència</th>
              <th>Quantitat</th>
              <th>Accions</th>
            </tr>
          </thead>
          <tbody>
            {products.map((p) => (
              <tr key={p.id}>
                <td>{p.nom}</td>
                <td>{p.referencia}</td>
                <td>{p.quantitat}</td>
                <td>
                  <button
                    className="btn btn-sm btn-primary me-2"
                    onClick={() => handleEdit(p)}
                  >
                    Editar
                  </button>
                  <button
                    className="btn btn-sm btn-danger"
                    onClick={() => handleDelete(p.id)}
                  >
                    Eliminar
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* ======================
          MODAL EDITAR
      ====================== */}
      {showModal && (
        <div
          className="modal fade show d-block"
          style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}
        >
          <div className="modal-dialog">
            <div className="modal-content">
              <form onSubmit={handleSubmit}>
                <div className="modal-header">
                  <h5 className="modal-title">Editar producte</h5>
                  <button
                    type="button"
                    className="btn-close"
                    onClick={() => setShowModal(false)}
                  />
                </div>

                <div className="modal-body">
                  <div className="mb-3">
                    <label>Nom</label>
                    <input
                      className="form-control"
                      name="nom"
                      value={form.nom}
                      onChange={handleChange}
                    />
                  </div>

                  <div className="mb-3">
                    <label>Referència</label>
                    <input
                      className="form-control"
                      name="referencia"
                      value={form.referencia}
                      onChange={handleChange}
                    />
                  </div>

                  <div className="mb-3">
                    <label>Descripció</label>
                    <textarea
                      className="form-control"
                      name="descripcio"
                      value={form.descripcio || ''}
                      onChange={handleChange}
                    />
                  </div>

                  <div className="mb-3">
                    <label>Quantitat</label>
                    <input
                      type="number"
                      className="form-control"
                      name="quantitat"
                      value={form.quantitat}
                      onChange={handleChange}
                    />
                  </div>
                </div>

                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => setShowModal(false)}
                  >
                    Cancel·lar
                  </button>
                  <button type="submit" className="btn btn-primary">
                    Guardar
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ProductsList;
